    {
        std::ostringstream oss;
        assert(z.readEntry(dataEntry, oss, ZipArchive::Current, 1024) == LIBZIPPP_OK);
        std::string s = oss.str();
        assert(s.size() == 7000);
        for (int i = 0; i < 7000; i++) {
            if (i == 100 || i == 4000) assert(s[i] == 0);
            else assert(s[i] == (char)(i % 251));
        }
    }

    // 2. ostream failing silently (failbit, no exceptions) -> OWRITE_FAILURE, state kept
    {
        FailingBuf buf;
        std::ostream os(&buf);
        assert(os.exceptions() == std::ios_base::goodbit);
        int r = z.readEntry(dataEntry, os, ZipArchive::Current, 1024);
        assert(r == LIBZIPPP_ERROR_OWRITE_FAILURE);
        assert(os.fail()); // failure state left as-is, not cleared
    }

