#include "libzippp.h"
#include <cassert>
#include <cstring>
#include <iostream>
#include <sstream>
#include <stdexcept>

using namespace libzippp;

static const char* ZIP = "test_exc.zip";

// streambuf whose writes always fail without throwing
struct FailingBuf : std::streambuf {
    std::streamsize xsputn(const char*, std::streamsize) override { return 0; }
};

// streambuf that throws a custom (non ios_base::failure) exception on write
struct ThrowingBuf : std::streambuf {
    std::streamsize xsputn(const char*, std::streamsize) override {
        throw std::runtime_error("custom sink failure");
    }
};

// streambuf that throws std::ios_base::failure directly from xsputn
struct IosThrowingBuf : std::streambuf {
    std::streamsize xsputn(const char*, std::streamsize) override {
        throw std::ios_base::failure("direct ios failure from buf");
    }
};

int main() {
    // build an archive: normal entry (with embedded zero bytes) + empty entry
    {
        ZipArchive z(ZIP);
        z.open(ZipArchive::Write);
        char content[7000];
        for (int i = 0; i < 7000; i++) content[i] = (char)(i % 251);
        content[100] = 0; // embedded zero byte
        content[4000] = 0;
        z.addData("data.bin", content, sizeof(content));
        z.addData("empty.bin", "", 0);
        z.close();
    }

    ZipArchive z(ZIP);
    z.open(ZipArchive::ReadOnly);
    ZipEntry dataEntry = z.getEntry("data.bin");
    ZipEntry emptyEntry = z.getEntry("empty.bin");
    assert(!dataEntry.isNull() && !emptyEntry.isNull());

    // 1. sanity: normal read via ostream, chunked, zero bytes preserved
    {
        std::ostringstream oss;
        assert(z.readEntry(dataEntry, oss, ZipArchive::Current, 1024) == LIBZIPPP_OK);
        std::string s = oss.str();
        assert(s.size() == 7000);
        for (int i = 0; i < 7000; i++) {
            if (i == 100 || i == 4000) assert(s[i] == 0);
            else assert(s[i] == (char)(i % 251));
        }
    }

    // 2. ostream failing silently (failbit, no exceptions) -> OWRITE_FAILURE, state kept
    {
        FailingBuf buf;
        std::ostream os(&buf);
        assert(os.exceptions() == std::ios_base::goodbit);
        int r = z.readEntry(dataEntry, os, ZipArchive::Current, 1024);
        assert(r == LIBZIPPP_ERROR_OWRITE_FAILURE);
        assert(os.fail()); // failure state left as-is, not cleared
    }

    // 3. ostream throwing ios_base::failure via its exception mask -> OWRITE_FAILURE,
    //    mask and state preserved
    {
        FailingBuf buf;
        std::ostream os(&buf);
        os.exceptions(std::ios_base::failbit | std::ios_base::badbit);
        int r = z.readEntry(dataEntry, os, ZipArchive::Current, 1024);
        assert(r == LIBZIPPP_ERROR_OWRITE_FAILURE);
        assert(os.exceptions() == (std::ios_base::failbit | std::ios_base::badbit));
        assert(os.fail());
    }

    // 3b. streambuf throwing ios_base::failure directly -> still OWRITE_FAILURE for the
    //     ostream entry point
    {
        IosThrowingBuf buf;
        std::ostream os(&buf);
        int r = z.readEntry(dataEntry, os, ZipArchive::Current, 1024);
        assert(r == LIBZIPPP_ERROR_OWRITE_FAILURE);
    }

    // 4. ostream write throwing another exception type -> propagates unchanged
    {
        ThrowingBuf buf;
        std::ostream os(&buf);
        bool caught = false;
        try {
            z.readEntry(dataEntry, os, ZipArchive::Current, 1024);
        } catch (const std::runtime_error& e) {
            caught = true;
            assert(std::string(e.what()) == "custom sink failure");
        }
        assert(caught);
    }

    // 5. callback returning false -> OWRITE_FAILURE, called exactly once after failure
    {
        int calls = 0;
        int r = z.readEntry(dataEntry, [&calls](const void*, libzippp_uint64) {
            calls++;
            return false;
        }, ZipArchive::Current, 1024);
        assert(r == LIBZIPPP_ERROR_OWRITE_FAILURE);
        assert(calls == 1);
    }

    // 6. callback throwing std::ios_base::failure -> propagated as-is, NOT converted
    {
        int calls = 0;
        bool caught = false;
        try {
            z.readEntry(dataEntry, [&calls](const void*, libzippp_uint64) -> bool {
                calls++;
                throw std::ios_base::failure("callback says no");
            }, ZipArchive::Current, 1024);
        } catch (const std::ios_base::failure& e) {
            caught = true;
            assert(std::string(e.what()).find("callback says no") != std::string::npos);
        }
        assert(caught);
        assert(calls == 1);
    }

    // 7. callback throwing a custom exception -> propagated with type and payload
    {
        struct MyError { int code; };
        bool caught = false;
        std::function<bool(const void*,libzippp_uint64)> cb = [](const void*, libzippp_uint64) -> bool {
            throw MyError{42};
        };
        try {
            z.readEntry(dataEntry, cb, ZipArchive::Current, 1024);
        } catch (const MyError& e) {
            caught = true;
            assert(e.code == 42);
        }
        assert(caught);
    }

    // 8. empty entry: single zero-length delivery; false -> OWRITE_FAILURE
    {
        int calls = 0;
        libzippp_uint64 gotSize = 1;
        int r = z.readEntry(emptyEntry, [&](const void*, libzippp_uint64 n) {
            calls++; gotSize = n; return false;
        });
        assert(r == LIBZIPPP_ERROR_OWRITE_FAILURE);
        assert(calls == 1 && gotSize == 0);
    }

    // 9. empty entry: throwing callback -> propagates unchanged
    {
        bool caught = false;
        try {
            z.readEntry(emptyEntry, [](const void*, libzippp_uint64) -> bool {
                throw std::runtime_error("empty boom");
            });
        } catch (const std::runtime_error& e) {
            caught = true;
            assert(std::string(e.what()) == "empty boom");
        }
        assert(caught);
    }

    // 10. empty entry via ostream with exceptions enabled -> OWRITE_FAILURE
    {
        FailingBuf buf;
        std::ostream os(&buf);
        os.exceptions(std::ios_base::failbit | std::ios_base::badbit);
        assert(z.readEntry(emptyEntry, os) == LIBZIPPP_ERROR_OWRITE_FAILURE);
    }

    // 11. repeated failures do not break the archive; a good receiver reads fully again
    {
        for (int i = 0; i < 5; i++) {
            FailingBuf buf;
            std::ostream os(&buf);
            assert(z.readEntry(dataEntry, os, ZipArchive::Current, 512) == LIBZIPPP_ERROR_OWRITE_FAILURE);
        }
        std::ostringstream oss;
        assert(dataEntry.readContent(oss, ZipArchive::Current, 512) == LIBZIPPP_OK);
        assert(oss.str().size() == 7000);
    }

    // 12. readEntry(string,...) full read still works after all the failures
    {
        void* content = z.readEntry("data.bin", false);
        assert(content != nullptr);
        assert(memcmp(((char*)content) + 101, "", 0) == 0);
        delete[] (char*)content;
    }

    z.close();

    // 13. writable archive still usable after failed reads: modify and commit
    {
        ZipArchive zw(ZIP);
        zw.open(ZipArchive::Write);
        ZipEntry e = zw.getEntry("data.bin");
        assert(!e.isNull());
        // failing read on a writable archive
        FailingBuf buf;
        std::ostream os(&buf);
        assert(zw.readEntry(e, os, ZipArchive::Current, 1024) == LIBZIPPP_ERROR_OWRITE_FAILURE);
        // Current vs Original with a pending replacement
        const char* repl = "replacement-content";
        zw.addData("data.bin", repl, strlen(repl));
        std::ostringstream cur, orig;
        assert(zw.readEntry(e, cur, ZipArchive::Current) == LIBZIPPP_OK);
        assert(zw.readEntry(e, orig, ZipArchive::Original) == LIBZIPPP_OK);
        assert(cur.str() == "replacement-content");
        assert(orig.str().size() == 7000);
        assert(zw.close());
    }

    // verify committed content
    {
        ZipArchive zr(ZIP);
        zr.open(ZipArchive::ReadOnly);
        void* c = zr.readEntry("data.bin", true);
        assert(std::string((char*)c) == "replacement-content");
        delete[] (char*)c;
        zr.close();
    }

    std::remove(ZIP);
    std::cout << "ALL TESTS PASSED" << std::endl;
    return 0;
}

