624	        if (result!=0) {
625	            //typically a cancelled commit: the archive is still open and usable, the
626	            //session is left untouched so existing entries and their copies remain valid
627	            Helper::callErrorHandlingCallback(zipHandle, "unable to close archive: %s\n", errorHandlingCallback);
